      "Preheat the air fryer to 400°F. Similar to preheating your oven, it’s a good idea to preheat your air fryer so the chicken nuggets can cook evenly and get crispy on the outside. Once preheated, place the chicken nuggets in the air fryer basket in a single layer. Try not to overcrowd the basket. You can cook the chicken nuggets in 2 batches if needed. Air fry for 8 minutes, flipping the nuggets halfway through.",
