    "title": "Oven Baked Chicken Drumsticks",
    "description": "This oven-baked chicken drumstick recipe is the perfect dinner idea that can be flavored with any of your favorite seasonings.",
    "image": "https://www.budgetbytes.com/wp-content/uploads/2021/08/Baked-Chicken-Drumsticks-Pan.jpg",
    "prepTime": 5,
    "cookTime": 40,
