      "1/2 tsp garlic powder ($0.05)",
      "1/4 tsp onion powder ($0.03)",
      "1/8 tsp cayenne pepper ($0.02)",
      "1/4 tsp dried oregano ($0.03)",
      "1/2 tsp salt ($0.02)",
      "1/4 tsp black pepper (freshly cracked, $0.02)",
      "1.75 lbs. chicken drumsticks (6 pieces, $4.23 *)",
