    "id": "chicken-alfredo",
    "title": "Chicken Alfredo",
    "description": "This Chicken Alfredo recipe features pasta drenched in an ultra-rich and creamy sauce, topped with juicy strips of seared chicken.",
    "image": "https://www.budgetbytes.com/wp-content/uploads/2022/07/Chicken-Alfredo-above.jpg",
