      "4 cloves garlic ($0.32)",
      "2 carrots ($0.24)",
      "1 zucchini (1/2 lb.) ($0.77)",
      "15 oz can diced tomatoes ($0.65)",
      "15 oz can tomato sauce ($0.70)",
